WITH valid AS (SELECT *, FLOOR(quantity) quantity_whole FROM inventory WHERE last_restock > DATE '2023-04-03') SELECT *, LAST_VALUE(quantity) IGNORE NULLS OVER (PARTITION BY store_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_quantity, PERCENT_RANK() OVER (PARTITION BY product_id, store_id ORDER BY quantity DESC) quantity_percent_rank FROM valid
